(function(){'use strict';const Auth=window.BTTAuth;if(!Auth){console.error('[dashboard] site_auth.js missing');return;}
const $=(id)=>document.getElementById(id);const $loading=$('dash-loading');const $body=$('dash-body');const $avatar=$('dash-avatar');const $sideName=$('dash-side-name');const $wonBadge=$('dash-won-badge');const $gwList=$('dash-gw-list');const $profUsername=$('prof-username');const $profEmail=$('prof-email');const $profDisplayName=$('prof-display-name');const $profEditName=$('prof-edit-name');const $profCreated=$('prof-created');const $logout=$('dash-logout');const $troveTagUnverified=$('trove-tag-unverified');const $troveTagVerified=$('trove-tag-verified');const $claimState=$('trove-claim-state');const $claimForm=$('trove-claim-form');const $claimInput=$('trove-name-input');const $claimError=$('trove-claim-error');const $claimedState=$('trove-claimed-state');const $claimedName=$('trove-claimed-name');const $claimedWhen=$('trove-claimed-when');const $unclaim=$('trove-unclaim');const $verifyBlock=$('trove-verify-block');const $verifyBtn=$('trove-verify-btn');const $verifyBaseline=$('trove-verify-baseline');const $verifyWhen=$('trove-verify-when');const $verifyResult=$('trove-verify-result');const $stats=$('dash-stats');const $statsMeta=$('dash-stats-meta');const $statsBody=$('dash-stats-body');boot().catch((err)=>{console.error('[dashboard] boot failed',err);showError(err);});async function boot(){if(!Auth.tokens.access){redirectToLogin();return;}
const user=await Auth.getMe({force:true});if(!user){redirectToLogin();return;}
renderUser(user);setupSections();loadMyGiveaways();if(user.claimed_trove_name)await loadTroveStats();}
function redirectToLogin(){location.href='/login?next=/dashboard';}
function showError(err){if($loading)$loading.innerHTML=`<p class="dash-error">${esc(t('Failed to load'))}: ${esc((err && err.message) || String(err))}</p>`;}
function renderUser(user){if($loading)$loading.hidden=true;if($body)$body.hidden=false;if($sideName)$sideName.textContent=user.display_name||user.username;if($avatar&&user.avatar_url){$avatar.src=user.avatar_url;$avatar.hidden=false;}
if($profUsername)$profUsername.textContent=user.username;if($profEmail)$profEmail.textContent=user.email;if($profDisplayName)$profDisplayName.textContent=user.display_name||t('(none set)');if($profCreated)$profCreated.textContent=formatDate(user.created_at);if(user.claimed_trove_name){$claimState.hidden=true;$claimedState.hidden=false;$claimedName.textContent=user.claimed_trove_display||user.claimed_trove_name;$claimedWhen.textContent=user.claimed_at?t('Claimed {when}').replace('{when}',formatDate(user.claimed_at)):'';renderVerifyBlock(user);if($stats)$stats.hidden=false;}else{$claimState.hidden=false;$claimedState.hidden=true;if($troveTagUnverified)$troveTagUnverified.hidden=true;if($troveTagVerified)$troveTagVerified.hidden=true;if($verifyBlock)$verifyBlock.hidden=true;if($stats)$stats.hidden=true;}
wireActions(user);}
function renderVerifyBlock(user){if(!$verifyBlock)return;$verifyBlock.hidden=false;const verified=!!user.claim_verified;$verifyBlock.dataset.state=verified?'verified':'unverified';if($troveTagUnverified)$troveTagUnverified.hidden=verified;if($troveTagVerified)$troveTagVerified.hidden=!verified;const $unv=$verifyBlock.querySelector('.dash-verify-unverified');const $ver=$verifyBlock.querySelector('.dash-verify-verified');if($unv)$unv.hidden=verified;if($ver)$ver.hidden=!verified;if(verified){if($verifyWhen){$verifyWhen.textContent=user.claim_verified_at?t('Verified {when}').replace('{when}',formatDate(user.claim_verified_at)):'';}}else{if($verifyBaseline){const n=user.claim_baseline_board_count||0;$verifyBaseline.textContent=n>0?t('We have a baseline on {n} board(s) - score on any of them to verify.').replace('{n}',String(n)):t("We didn't capture any leaderboard data for that name at claim time. Play a bit, then click Verify to re-check.");}}
if($verifyResult)$verifyResult.hidden=true;}
function wireActions(user){if($profEditName){$profEditName.onclick=async()=>{const next=prompt(t('New display name (blank to clear):'),user.display_name||'');if(next===null)return;const r=await Auth.callJSON('/v1/site-auth/me',{method:'PATCH',json:{display_name:next.trim()||null},});if(r.ok&&r.data)renderUser(r.data);};}
if($logout){$logout.onclick=async()=>{await Auth.logout();location.href='/';};}
if($claimForm){$claimForm.onsubmit=async(e)=>{e.preventDefault();$claimError.hidden=true;const name=($claimInput.value||'').trim();if(!name)return;const r=await Auth.callJSON('/v1/site-auth/me/claim-trove-name',{method:'POST',json:{trove_name:name},});if(!r.ok){$claimError.textContent=Auth.errorMessage(r.data)||t('Failed to claim that name.');$claimError.hidden=false;return;}
renderUser(r.data);await loadTroveStats();};}
if($unclaim){$unclaim.onclick=async()=>{if(!confirm(t('Release this Trove name? You can re-claim later.')))return;const r=await Auth.callJSON('/v1/site-auth/me/claim-trove-name',{method:'DELETE',});if(r.ok&&r.data)renderUser(r.data);};}
if($verifyBtn){$verifyBtn.onclick=async()=>{$verifyBtn.disabled=true;const prevLabel=$verifyBtn.textContent;$verifyBtn.textContent=t('Checking…');try{const r=await Auth.callJSON('/v1/site-auth/me/verify-trove-claim',{method:'POST',});if(!r.ok){if($verifyResult){$verifyResult.textContent=Auth.errorMessage(r.data)||t('Verification failed.');$verifyResult.dataset.tone='error';$verifyResult.hidden=false;}
return;}
if(r.data.user)renderUser(r.data.user);if($verifyResult){$verifyResult.textContent=r.data.detail||'';$verifyResult.dataset.tone=r.data.verified?'success':'info';$verifyResult.hidden=false;}}finally{$verifyBtn.disabled=false;$verifyBtn.textContent=prevLabel;}};}}
const SECTIONS=['profile','giveaways','leaderboard'];function setupSections(){document.querySelectorAll('.dash-nav-item').forEach((b)=>b.addEventListener('click',()=>showSection(b.dataset.section)));const hash=location.hash.replace(/^#/,'');showSection(SECTIONS.includes(hash)?hash:'profile');window.addEventListener('hashchange',()=>{const h=location.hash.replace(/^#/,'');if(SECTIONS.includes(h))showSection(h);});}
function showSection(name){document.querySelectorAll('.dash-nav-item').forEach((b)=>b.classList.toggle('active',b.dataset.section===name));document.querySelectorAll('.dash-section').forEach((s)=>{s.hidden=s.dataset.pane!==name;});if(location.hash.replace(/^#/,'')!==name)history.replaceState(null,'','#'+name);}
async function loadMyGiveaways(){if(!$gwList)return;const r=await Auth.callJSON('/v1/giveaways/me');if(!r.ok||!Array.isArray(r.data)){$gwList.innerHTML=`<p class="dash-empty">${esc(t("Couldn't load your giveaways right now."))}</p>`;return;}
const items=r.data;const won=items.filter((g)=>g.won).length;if($wonBadge){$wonBadge.hidden=won===0;$wonBadge.textContent=String(won);}
if(!items.length){$gwList.innerHTML=`<p class="dash-empty">${esc(t("You haven't entered any giveaways yet."))} <a href="/giveaways">${esc(t('Browse giveaways'))}</a>.</p>`;return;}
$gwList.innerHTML=items.map(gwCard).join('');$gwList.querySelectorAll('[data-copy]').forEach((b)=>b.addEventListener('click',()=>{if(navigator.clipboard)navigator.clipboard.writeText(b.dataset.copy);const prev=b.textContent;b.textContent=t('Copied!');setTimeout(()=>{b.textContent=prev;},1500);}));}
function gwCard(g){let status=g.status,cls='';if(g.won){status=t('🎉 You won!');cls='won';}
else if(g.status==='drawn'){status=t('Not selected');cls='lost';}
else if(g.status==='open'){status=t('Entered · draw pending');cls='pending';}
const code=(g.won&&g.code)?`
      <div class="gw-my-code">
        <code>${esc(g.code)}</code>
        <button type="button" class="dash-btn dash-btn-mini" data-copy="${esc(g.code)}">${esc(t('Copy'))}</button>
      </div>`:'';return`
      <article class="gw-my-card ${g.won ? 'won' : ''}">
        <div class="gw-my-head">
          <div class="gw-my-info">
            <p class="gw-my-prize">${esc(g.prize_name)}</p>
            <p class="gw-my-title">${esc(g.title)}</p>
          </div>
          <span class="gw-my-status ${cls}">${esc(status)}</span>
        </div>
        ${code}
      </article>`;}
async function loadTroveStats(){$statsBody.innerHTML=`<p class="dash-loading" data-i18n>${t('Crunching the latest capture - first paint can take a moment while we warm the caches.')}</p>`;const r=await Auth.callJSON('/v1/site-auth/me/trove-stats');if(!r.ok||!r.data){$statsBody.innerHTML=`<p class="dash-error">${esc(t('Could not load your stats right now.'))}</p>`;return;}
const items=r.data.items||[];const series=r.data.series||null;if(!items.length){$statsBody.innerHTML=`
        <p class="dash-empty">${esc(t('No recent leaderboard appearances for this player name yet. The bot captures hourly - check back after the next sweep, or pick a different name.'))}</p>`;$statsMeta.textContent='';return;}
if($statsMeta){$statsMeta.textContent=t('{n} recent appearance(s)').replace('{n}',items.length);}
const rows=items.slice(0,25).map((it)=>`
      <div class="dash-stat-row">
        <span class="dash-stat-board">${esc(t('Board') + ' #' + it.leaderboard)}</span>
        <span class="dash-stat-rank">#${it.rank}</span>
        <span class="dash-stat-score">${esc(formatScore(it.score))}</span>
        <span class="dash-stat-when">${esc(formatWhen(it.created_at))}</span>
      </div>`).join('');let chartHTML='';if(series&&(series.series||[]).length){const lines=series.series.slice(0,6).map((s)=>({label:s.name,bestRank:s.best_rank,points:s.points,}));chartHTML=`
        <div class="dash-chart" id="dash-chart-host">${renderInlineChart(series.anchors, lines)}</div>
        <ul class="dash-chart-legend">
          ${lines.map((l, i) => `<li><span class="dash-chart-swatch"style="background:${chartColor(i)}"></span><span class="dash-chart-name"title="${esc(l.label)}">${esc(l.label)}</span><span class="dash-chart-best">${esc(t('best #'+l.bestRank))}</span></li>`).join('')}
        </ul>`;}
$statsBody.innerHTML=`
      ${chartHTML}
      <div class="dash-stat-table" role="table">${rows}</div>`;}
function renderInlineChart(anchors,series){if(!anchors||anchors.length<2||!series.length)return'';const W=720,H=180,PAD=28;const xMin=anchors[0],xMax=anchors[anchors.length-1];const xRange=Math.max(1,xMax-xMin);let yMin=Infinity,yMax=-Infinity;for(const s of series)for(const p of s.points){if(p.score<yMin)yMin=p.score;if(p.score>yMax)yMax=p.score;}
if(!isFinite(yMin)||!isFinite(yMax))return'';if(yMin===yMax){yMin-=1;yMax+=1;}
const pad=(yMax-yMin)*0.08;yMin-=pad;yMax+=pad;const yRange=yMax-yMin;const x=(t)=>PAD+((t-xMin)/xRange)*(W-PAD*2);const y=(v)=>PAD+(1-(v-yMin)/yRange)*(H-PAD*2);const polylines=series.map((s,i)=>{const pts=s.points.map((p)=>`${x(p.created_at).toFixed(1)},${y(p.score).toFixed(1)}`).join(' ');return`<polyline fill="none" stroke="${chartColor(i)}" stroke-width="2" stroke-linejoin="round" points="${pts}"></polyline>`;}).join('');return`
      <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img">
        ${polylines}
      </svg>`;}
const CHART_COLORS=['#4cc9f0','#f72585','#43aa8b','#f8961e','#b5179e','#4361ee','#f9c74f','#7209b7',];function chartColor(i){return CHART_COLORS[i%CHART_COLORS.length];}
function formatScore(score){return Number.isInteger(score)?score.toLocaleString():Number(score).toLocaleString(undefined,{maximumFractionDigits:2});}
function formatDate(iso){if(!iso)return'';const d=new Date(iso);if(isNaN(d.getTime()))return'';const pad=(n)=>String(n).padStart(2,'0');return`${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;}
function formatWhen(unix){const d=new Date(unix*1000);if(isNaN(d.getTime()))return'';const pad=(n)=>String(n).padStart(2,'0');return`${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())} UTC`;}
function t(s){return window.BTTi18n&&window.BTTi18n.t?window.BTTi18n.t(s):s;}
function esc(s){return String(s??'').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}})();